// Demo for the C++ RL-Switch meta policy.
//
//   g++ -std=c++17 -O2 cpp/rl_switch_demo.cpp -o rl_switch_demo
//   ./rl_switch_demo
//
// The weights header is generated by:
//   python3 -m ipd.tools.export_switch_cpp \
//     --base weights/rl_policy_weights_wide160.json \
//     --alt weights/rl_policy_weights_repair.json \
//     --out cpp/rl_switch_weights.hpp
#include <cstdio>
#include <vector>

#include "policies/rl_switch_policy.hpp"

int main() {
    ipd::RLSwitchParams params;
    params.sample = false;
    ipd::RLSwitchPolicy policy(20261024u, params);
    std::printf("features=%zu\n", policy.features({}, {}).size());
    std::vector<int> mine, theirs;
    for (int t = 0; t < 100; ++t) {
        const int reply = (t < 2) ? ipd::D : ipd::C;
        const int action = policy.act(t, mine, theirs);
        mine.push_back(action);
        theirs.push_back(reply);
    }
    std::printf("switched=%d score=%d\n", int(policy.switched()),
                ipd::payoff(mine.back(), theirs.back()));
    return 0;
}
